import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long n = sc.nextLong();
            int k = sc.nextInt();

            List<Long> arr = new ArrayList<>();
            for (int i = 0; i < k + 3; i++) {
                arr.add(0L);
            }
            arr.set(k, 1L);
            arr.set(k + 1, 1L);
            arr.set(k + 2, 1L);

            long power = 1;
            int digitsCount = 0;
            while (power <= n / k) {
                power *= k;
                digitsCount++;
            }

            List<List<Long>> P = new ArrayList<>();
            for (int i = 0; i <= digitsCount; i++) {
                List<Long> row = new ArrayList<>();
                for (int j = 0; j < k + 3; j++) {
                    row.add(0L);
                }
                P.add(row);
            }

            for (int i = 0; i < k; i++) {
                P.get(0).set(i, 0L);
            }
            P.get(0).set(k, 1L);
            P.get(0).set(k + 1, 1L);
            P.get(0).set(k + 2, 1L);

            long off = 0;
            int d_idx = digitsCount;
            while (power > 0) {
                int t = (int)((n - off) / power);
                for (int j = 0; j < t; j++) {
                    int s = 0; // dummy
                    for (int i = 0; i < k; i++) {
                        arr.set(i, arr.get(i) + s);
                    }
                    off += power;
                }
                power /= k;
                d_idx--;
            }
            System.out.println(arr.get(k + 1));
        }
        sc.close();
    }
}
